var readers = map[string]func([]byte) (Event, error){
    "order-created": parseOrderCreated,
    "order-shipped": parseOrderShipped,
}
func handle(m kafka.Message) error {
    tok := headerValue(m.Headers, "content-type")   // []byte, may be absent
    parse, ok := readers[tok]
    if !ok { return fmt.Errorf("unknown message type %q", tok) }
    _, err := parse(m.Value)
    return err
}
